#!/bin/sh
# Install the geni-uploader man pages under $PREFIX (default /usr/local):
#   tools/install_man_pages.sh
#   PREFIX="$HOME/.local" tools/install_man_pages.sh
# The pages are generated by tools/build_man_pages.py; do not edit them.
set -eu
PREFIX="${PREFIX:-/usr/local}"
SRC="$(CDPATH= cd -- "$(dirname -- "$0")/../man/man1" && pwd)"
DEST="$PREFIX/share/man/man1"
install -d "$DEST"
COUNT=0
for page in "$SRC"/*.1; do
  install -m 0644 "$page" "$DEST/"
  COUNT=$((COUNT + 1))
done
echo "installed $COUNT man pages to $DEST"
